import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows significant association with outcome
    # Use Welch's t-test to assess difference in means between outcome groups
    significant_features = []

    for i, fid in enumerate(feats.ids):
        # Split data by outcome
        x0 = feats.x[feats.y == 0, i]
        x1 = feats.x[feats.y == 1, i]

        # Welch's t-test
        if len(x0) > 1 and len(x1) > 1:
            t_stat, p_val = stats.ttest_ind(x0, x1, equal_var=False)
            if abs(t_stat) > 3.0 and p_val < 0.01:
                mean_diff = np.mean(x1) - np.mean(x0)
                significant_features.append((fid, mean_diff, abs(t_stat), p_val))

    # Sort by t-statistic magnitude (strongest first)
    significant_features.sort(key=lambda x: -x[2])

    # Check for near-duplicates using correlation matrix
    corr_matrix = np.corrcoef(feats.x.T)
    near_duplicates = set()

    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i, j]) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                # Keep the one with stronger association
                if (fid1, fid2) not in near_duplicates and (fid2, fid1) not in near_duplicates:
                    near_duplicates.add((fid1, fid2))

    # Remove near-duplicates (keep the first one in sorted list)
    filtered_features = []
    used_fids = set()

    for fid, mean_diff, t_stat, p_val in significant_features:
        skip = False
        for dup_fid1, dup_fid2 in near_duplicates:
            if fid in [dup_fid1, dup_fid2]:
                if dup_fid1 in used_fids or dup_fid2 in used_fids:
                    skip = True
                    break
                else:
                    used_fids.add(fid)
                    filtered_features.append((fid, mean_diff, t_stat, p_val))
                    used_fids.add(dup_fid1)
                    used_fids.add(dup_fid2)
                    break

        if not skip and fid not in used_fids:
            used_fids.add(fid)
            filtered_features.append((fid, mean_diff, t_stat, p_val))

    # Test for interaction effects
    products = []
    if len(filtered_features) >= 2:
        # Try all pairs of significant features
        for i in range(min(3, len(filtered_features))):
            for j in range(i+1, min(5, len(filtered_features))):
                f1, _, _, _ = filtered_features[i]
                f2, _, _, _ = filtered_features[j]
                products.append((f1, f2))

    # Check stratum consistency (simple check)
    stratum_consistent = True
    if len(set(feats.stratum)) > 1:
        stratum_consistent = False  # Simplified approach

    # Return appropriate design based on evidence
    if not filtered_features or not stratum_consistent:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features for model - limit to MAX_DRIVERS
    drivers = tuple(f[0] for f in filtered_features[:min(MAX_DRIVERS, len(filtered_features))])
    columns = tuple(f[0] for f in filtered_features[:10])  # Top 10 for regression
    loadings = dict(zip(columns, np.ones(len(columns))))

    # Ensure we don't exceed MAX_DRIVERS
    if len(drivers) > MAX_DRIVERS:
        drivers = drivers[:MAX_DRIVERS]

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
